/**
 * Node-RED Backend API Storage Module
 * 
 * 這個模組將 Node-RED 的流程存儲到後端 API 伺服器
 * 而不是使用本地文件系統
 * 
 * 配置方式：在 settings.js 中設定
 * storageModule: require("./storage/backend-api"),
 * backendApiUrl: "http://localhost:8080/api/v1/nodered",
 * backendFlowName: "default"  // 可選，流程名稱
 */

const axios = require('axios');
const log = require("@node-red/util").log;

let settings;
let apiUrl;
let flowName;

/**
 * 發送 HTTP 請求到後端 API
 */
async function apiRequest(method, endpoint, data = null) {
    const url = `${apiUrl}${endpoint}`;
    const config = {
        method,
        url,
        headers: {
            'Content-Type': 'application/json'
        },
        timeout: 30000
    };

    if (data) {
        config.data = data;
    }

    try {
        const response = await axios(config);
        return response.data;
    } catch (error) {
        if (error.response) {
            log.error(`Backend API Error: ${error.response.status} - ${JSON.stringify(error.response.data)}`);
            throw new Error(`Backend API Error: ${error.response.data.message || error.message}`);
        } else if (error.request) {
            log.error(`Backend API No Response: ${error.message}`);
            throw new Error(`Backend API No Response: ${error.message}`);
        } else {
            log.error(`Backend API Request Error: ${error.message}`);
            throw new Error(`Backend API Request Error: ${error.message}`);
        }
    }
}

const backendApiStorage = {
    /**
     * 初始化存儲模組
     * @param {Object} _settings - Node-RED 設定
     * @param {Object} runtime - Node-RED runtime
     */
    init: async function (_settings, runtime) {
        settings = _settings;

        // 從設定中獲取後端 API URL
        apiUrl = settings.backendApiUrl || process.env.NODERED_BACKEND_API_URL || 'http://localhost:8080/api/v1/nodered';
        flowName = settings.backendFlowName || process.env.NODERED_FLOW_NAME || 'default';

        log.info(`Backend API Storage initialized`);
        log.info(`API URL: ${apiUrl}`);
        log.info(`Flow Name: ${flowName}`);

        // 驗證後端連接
        try {
            await apiRequest('GET', `/flows?name=${flowName}`);
            log.info('Backend API connection verified');
        } catch (error) {
            log.warn(`Backend API connection test failed: ${error.message}`);
            log.warn('Node-RED will continue but storage may not work properly');
        }
    },

    /**
     * 獲取流程
     * @returns {Promise<Array>} 流程數據
     */
    getFlows: async function () {
        try {
            const response = await apiRequest('GET', `/flows?name=${flowName}`);
            if (response.status === 'SUCCESS') {
                return response.data || [];
            }
            return [];
        } catch (error) {
            log.error(`Failed to get flows: ${error.message}`);
            return [];
        }
    },

    /**
     * 儲存流程
     * @param {Array} flows - 流程數據
     * @param {Object} user - 用戶信息（可選）
     * @returns {Promise<void>}
     */
    saveFlows: async function (flows, user) {
        try {
            const response = await apiRequest('POST', `/flows?name=${flowName}`, {
                flows: flows
            });
            if (response.status === 'SUCCESS') {
                log.info('Flows saved to backend successfully');
                return response.rev;
            }
            throw new Error(response.message || 'Failed to save flows');
        } catch (error) {
            log.error(`Failed to save flows: ${error.message}`);
            throw error;
        }
    },

    /**
     * 獲取憑證
     * @returns {Promise<Object>} 憑證數據
     */
    getCredentials: async function () {
        try {
            const response = await apiRequest('GET', `/credentials?name=${flowName}`);
            if (response.status === 'SUCCESS') {
                return response.data || {};
            }
            return {};
        } catch (error) {
            log.error(`Failed to get credentials: ${error.message}`);
            return {};
        }
    },

    /**
     * 儲存憑證
     * @param {Object} credentials - 憑證數據
     * @returns {Promise<void>}
     */
    saveCredentials: async function (credentials) {
        try {
            const response = await apiRequest('POST', `/credentials?name=${flowName}`, {
                credentials: credentials
            });
            if (response.status === 'SUCCESS') {
                log.info('Credentials saved to backend successfully');
                return;
            }
            throw new Error(response.message || 'Failed to save credentials');
        } catch (error) {
            log.error(`Failed to save credentials: ${error.message}`);
            throw error;
        }
    },

    /**
     * 獲取設定
     * @returns {Promise<Object>} 設定數據
     */
    getSettings: async function () {
        try {
            const response = await apiRequest('GET', `/settings?name=${flowName}`);
            if (response.status === 'SUCCESS') {
                return response.data || {};
            }
            return {};
        } catch (error) {
            log.error(`Failed to get settings: ${error.message}`);
            return {};
        }
    },

    /**
     * 儲存設定
     * @param {Object} settings - 設定數據
     * @returns {Promise<void>}
     */
    saveSettings: async function (newSettings) {
        try {
            const response = await apiRequest('POST', `/settings?name=${flowName}`, {
                settings: newSettings
            });
            if (response.status === 'SUCCESS') {
                log.info('Settings saved to backend successfully');
                return;
            }
            throw new Error(response.message || 'Failed to save settings');
        } catch (error) {
            log.error(`Failed to save settings: ${error.message}`);
            throw error;
        }
    },

    /**
     * 獲取會話
     * @returns {Promise<Object>} 會話數據
     */
    getSessions: async function () {
        try {
            const response = await apiRequest('GET', '/sessions');
            if (response.status === 'SUCCESS') {
                return response.data || {};
            }
            return {};
        } catch (error) {
            log.error(`Failed to get sessions: ${error.message}`);
            return {};
        }
    },

    /**
     * 儲存會話
     * @param {Object} sessions - 會話數據
     * @returns {Promise<void>}
     */
    saveSessions: async function (sessions) {
        try {
            const response = await apiRequest('POST', '/sessions', {
                sessions: sessions
            });
            if (response.status === 'SUCCESS') {
                log.info('Sessions saved to backend successfully');
                return;
            }
            throw new Error(response.message || 'Failed to save sessions');
        } catch (error) {
            log.error(`Failed to save sessions: ${error.message}`);
            throw error;
        }
    },

    /**
     * 獲取函數庫條目
     * @param {string} type - 類型（flows, functions）
     * @param {string} path - 路徑
     * @returns {Promise<Object|Array>} 條目數據
     */
    getLibraryEntry: async function (type, path) {
        try {
            // 如果是目錄請求（路徑以 / 結尾或是空的），返回列表
            if (!path || path === '/' || path.endsWith('/')) {
                const response = await apiRequest('GET', `/library?type=${type}&path=${encodeURIComponent(path || '/')}`);
                if (response.status === 'SUCCESS') {
                    // 返回目錄結構格式
                    const entries = response.data || [];
                    return entries.map(entry => {
                        if (entry.body) {
                            return { fn: entry.name, ...entry.meta };
                        }
                        return entry.name;
                    });
                }
                return [];
            }

            // 獲取單個條目
            const response = await apiRequest('GET', `/library/${type}${path.startsWith('/') ? path : '/' + path}`);
            if (response.status === 'SUCCESS' && response.data) {
                return response.data.body || response.data;
            }
            throw new Error('Library entry not found');
        } catch (error) {
            if (error.message && error.message.includes('404')) {
                // 返回空列表表示目錄為空
                return [];
            }
            log.error(`Failed to get library entry: ${error.message}`);
            throw error;
        }
    },

    /**
     * 儲存函數庫條目
     * @param {string} type - 類型（flows, functions）
     * @param {string} path - 路徑
     * @param {Object} meta - 元數據
     * @param {string} body - 內容
     * @returns {Promise<void>}
     */
    saveLibraryEntry: async function (type, path, meta, body) {
        try {
            const name = path.split('/').pop() || path;
            const response = await apiRequest('POST', '/library', {
                type: type,
                path: path,
                name: name,
                meta: meta,
                body: typeof body === 'string' ? body : JSON.stringify(body)
            });
            if (response.status === 'SUCCESS') {
                log.info(`Library entry saved: ${type}/${path}`);
                return;
            }
            throw new Error(response.message || 'Failed to save library entry');
        } catch (error) {
            log.error(`Failed to save library entry: ${error.message}`);
            throw error;
        }
    }
};

module.exports = backendApiStorage;
